-- =====================================================================
-- E2.4 - SCRIPT DE POVOAMENTO (SIRCA - Instituto Semear) - Equipe D - Ciclo 2
-- Rodar DEPOIS do script de criacao (E2.4_script_criacao_banco.sql).
--
-- PREMISSA DE VOLUME (nenhum documento fixa quantidade a povoar):
--   carga inicial = historico acumulado descrito no Dossie 2 (fotografia);
--   crescimento futuro = projecao do E1.7, tratada so no E2.7 (nao e inserido);
--   teste de desempenho (RNF-02) = dados a parte, nao misturados a esta carga.
--
-- RELATORIO DE CARGA (RNF-01)
--   FAMILIA            140 | PARTICIPANTE 225 | OFICINA 12 | OFICINEIRO 3
--   DOACAO             160 | ENCAMINHAMENTO 95
--   FREQUENCIA - arquivo bruto: 2.256 linhas
--     - linhas de recado ............  17  (2.256 - 17 = 2.239, igual ao E1.7)
--     - rejeitadas RF-07 ............   7  (OF13 x4, P999 x3)
--     - rejeitadas RN-03 ............   4  (duplicidade)
--     - rejeitadas RN-04 ............   3  (apos desligamento)
--     - ACEITAS ..................... 2225  (2.239 - 14)
--   Total em CARGA_REJEICAO: 31
--
-- CONVERSAO DE MARCAS DE PRESENCA (RN-01) - 11 marcas brutas -> 3 valores:
--   F           -> falta                188 linhas
--   FALTA       -> falta                 44 linhas
--   Falta       -> falta                 70 linhas
--   f           -> falta                 54 linhas
--   FJ          -> falta_justificada     45 linhas
--   J           -> falta_justificada     86 linhas
--   Justificada -> falta_justificada     35 linhas
--   P           -> presente            1013 linhas
--   PRESENTE    -> presente             165 linhas
--   Presente    -> presente             275 linhas
--   p           -> presente             250 linhas
--   (A lista das 11 marcas e uma PREMISSA desta base sintetica; ao carregar a
--    base oficial, substitua pela tabela de conversao real da equipe.)
--
-- OUTRAS PREMISSAS
--   * Linha_Origem em CARGA_REJEICAO refere-se ao arquivo bruto sintetico
--     (linha 1 = cabecalho). Recalcule ao usar a base oficial.
--   * Data_Hora_Lancamento historica nao existe na base bruta: usou-se a data do
--     encontro, no fim da tarde, como substituta.
--   * Registrado_Por = educador responsavel pela oficina; os educadores 2 e 3
--     sao identificados funcionalmente (E1.3 pede cargo/funcao, nao nome).
--   * RN-04 hoje so e aplicada pela carga; o banco nao a impede sozinho
--     (sugestao: trigger BEFORE INSERT em FREQUENCIA).
--   * Ocupacao da oficina (PN-06) = participantes distintos com frequencia / vagas.
-- =====================================================================

BEGIN;

-- 0. CARGA_REJEICAO: acrescenta 'RN-04' ao dominio de Regra_Violada
--    (o script de criacao so previa RF-07, RN-01, RN-03, linha_recado, outro).
--    Se preferir, ajuste o CHECK direto no CREATE TABLE do E2.4 e apague este bloco.
ALTER TABLE CARGA_REJEICAO DROP CONSTRAINT IF EXISTS carga_rejeicao_regra_violada_check;
ALTER TABLE CARGA_REJEICAO ADD CONSTRAINT carga_rejeicao_regra_violada_check
    CHECK (Regra_Violada IN ('RF-07','RN-01','RN-03','RN-04','linha_recado','outro'));

